actions.script:
const ids = Array.from(new Set(Array.from(userIdList || []).map((id) => String(id || '').trim()).filter((id) => id)))
ringUserIdList = ids
if (!ids.length) return
const now = Number(ec.user.nowTimestamp)
const dnd = new Set(Array.from(ec.entity.find('moqui.security.UserStatus').condition('userId', 'in', ids)
        .condition('statusEnumId', 'UpsDnd').disableAuthz().list())
        .filter((row) => row.clearAtDate == null || Number(row.clearAtDate) > now).map((row) => row.userId))
if (!dnd.size) return
const rings = new Set()
if (fromUserId) {
    for (const row of ec.entity.find('moqui.security.UserPreference').condition('userId', 'in', Array.from(dnd))
            .condition('preferenceKey', 'CHAT_DND_ALLOWED').disableAuthz().list()) {
        if (String(row.preferenceValue || '').split(',').map((id) => id.trim()).includes(fromUserId)) rings.add(row.userId)
    }
    // the same person's second call within 3 minutes
    const earlier = Array.from(ec.entity.find('moqui.call.CallUserLog').condition('userId', 'in', Array.from(dnd))
            .condition('roleEnumId', 'CurCallee').condition('logDate', 'greater-equals', new Date(now - 180000))
            .disableAuthz().list()).filter((row) => row.callSessionId !== callSessionId)
    if (earlier.length) {
        const byCaller = new Set(Array.from(ec.entity.find('moqui.call.CallSession')
                .condition('callSessionId', 'in', earlier.map((row) => row.callSessionId)).condition('startedByUserId', fromUserId)
                .selectField('callSessionId').disableAuthz().list()).map((row) => row.callSessionId))
        for (const row of earlier) if (byCaller.has(row.callSessionId)) rings.add(row.userId)
    }
}
ringUserIdList = ids.filter((id) => !dnd.has(id) || rings.has(id))
